import { readFileSync } from 'node:fs'

const KEYWORDS = new Set(['let', 'if', 'else', 'while', 'return', 'true', 'false', 'null'])
const PUNCT = ['==', '!=', '<=', '>=', '&&', '||', '->', '=>', '+', '-', '*', '/', '%', '=', '<', '>', '!', '(', ')', '{', '}', '[', ']', ',', ';', '.']
const KINDS = ['ident', 'keyword', 'number', 'punct', 'rawstring', 'string']

class ScanError extends Error {
  constructor(line, col, reason) {
    super(reason)
    this.line = line
    this.col = col
  }
}

const isDigit = (c) => c !== undefined && c >= '0' && c <= '9'
const isLetter = (c) => c !== undefined && ((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z'))
const isIdStart = (c) => isLetter(c) || c === '_'
const isIdPart = (c) => isIdStart(c) || isDigit(c)
const isHex = (c) => c !== undefined && /^[0-9a-fA-F]$/.test(c)

function scan(text) {
  const cs = Array.from(text)
  const n = cs.length
  const tokens = []
  let i = 0
  let line = 1
  let col = 1

  const adv = () => {
    const c = cs[i++]
    if (c === '\n') { line++; col = 1 }
    else if (c === '\t') col = Math.floor((col - 1) / 4) * 4 + 5
    else col++
    return c
  }
  const advN = (k) => { for (let j = 0; j < k; j++) adv() }

  while (i < n) {
    const c = cs[i]
    if (c === ' ' || c === '\t' || c === '\r' || c === '\n') { adv(); continue }
    const sl = line, sc = col
    if (c === '/' && cs[i + 1] === '/') {
      while (i < n && cs[i] !== '\n') adv()
      continue
    }
    if (c === '/' && cs[i + 1] === '*') {
      let depth = 0
      do {
        if (i >= n) throw new ScanError(sl, sc, 'unterminated block comment')
        if (cs[i] === '/' && cs[i + 1] === '*') { depth++; advN(2) }
        else if (cs[i] === '*' && cs[i + 1] === '/') { depth--; advN(2) }
        else adv()
      } while (depth > 0)
      continue
    }
    if (c === 'r' && cs[i + 1] === '"') {
      advN(2)
      let v = ''
      while (true) {
        if (i >= n) throw new ScanError(sl, sc, 'unterminated string')
        const d = adv()
        if (d === '"') break
        v += d
      }
      tokens.push({ line: sl, col: sc, kind: 'rawstring', body: JSON.stringify(v) })
      continue
    }
    if (isIdStart(c)) {
      let s = ''
      while (i < n && isIdPart(cs[i])) s += adv()
      tokens.push({ line: sl, col: sc, kind: KEYWORDS.has(s) ? 'keyword' : 'ident', body: s })
      continue
    }
    if (isDigit(c)) {
      let s = ''
      const run = (ok) => {
        // digit (digit | _ digit)*; returns count of digits consumed
        let k = 0
        if (!ok(cs[i])) return 0
        s += adv(); k++
        while (i < n) {
          if (ok(cs[i])) { s += adv(); k++ }
          else if (cs[i] === '_' && ok(cs[i + 1])) { s += adv(); s += adv(); k++ }
          else break
        }
        return k
      }
      let bad = false
      const p = cs[i + 1]
      let radixOk = null
      if (c === '0' && (p === 'x' || p === 'X')) radixOk = isHex
      else if (c === '0' && (p === 'b' || p === 'B')) radixOk = (d) => d === '0' || d === '1'
      else if (c === '0' && (p === 'o' || p === 'O')) radixOk = (d) => d !== undefined && d >= '0' && d <= '7'
      if (radixOk) {
        s += adv(); s += adv()
        if (run(radixOk) === 0) bad = true
      } else {
        run(isDigit)
        if (cs[i] === '.' && isDigit(cs[i + 1])) { s += adv(); run(isDigit) }
        const e = cs[i]
        if (e === 'e' || e === 'E') {
          const q = cs[i + 1]
          if (isDigit(q) || ((q === '+' || q === '-') && isDigit(cs[i + 2]))) {
            s += adv()
            if (!isDigit(cs[i])) s += adv()
            run(isDigit)
          }
        }
      }
      if (i < n && isIdPart(cs[i])) bad = true
      if (bad) {
        while (i < n && isIdPart(cs[i])) s += adv()
        throw new ScanError(sl, sc, `invalid number ${s}`)
      }
      tokens.push({ line: sl, col: sc, kind: 'number', body: s })
      continue
    }
    if (c === '"') {
      adv()
      let v = ''
      while (true) {
        if (i >= n) throw new ScanError(sl, sc, 'unterminated string')
        const el = line, ec = col
        const d = cs[i]
        if (d === '"') { adv(); break }
        if (d === '\n') throw new ScanError(el, ec, 'newline in string')
        if (d !== '\\') { v += adv(); continue }
        adv()
        if (i >= n) throw new ScanError(sl, sc, 'unterminated string')
        const e = adv()
        const bad = () => new ScanError(el, ec, `invalid escape \\${e}`)
        if (e === 'n') v += '\n'
        else if (e === 't') v += '\t'
        else if (e === 'r') v += '\r'
        else if (e === '\\') v += '\\'
        else if (e === '"') v += '"'
        else if (e === '0') v += '\0'
        else if (e === 'x') {
          if (!(isHex(cs[i]) && isHex(cs[i + 1]))) throw bad()
          v += String.fromCharCode(parseInt(cs[i] + cs[i + 1], 16))
          advN(2)
        } else if (e === 'u') {
          if (cs[i] !== '{') throw bad()
          let j = i + 1
          let h = ''
          while (isHex(cs[j])) h += cs[j++]
          if (h === '' || cs[j] !== '}') throw bad()
          const cp = parseInt(h, 16)
          if (cp > 0x10ffff) throw bad()
          v += String.fromCodePoint(cp)
          advN(j + 1 - i)
        } else throw bad()
      }
      tokens.push({ line: sl, col: sc, kind: 'string', body: JSON.stringify(v) })
      continue
    }
    const two = c + (cs[i + 1] ?? '')
    const m = PUNCT.find((p) => p.length === 2 && p === two) ?? PUNCT.find((p) => p === c)
    if (m) {
      advN(m.length)
      tokens.push({ line: sl, col: sc, kind: 'punct', body: m })
      continue
    }
    throw new ScanError(sl, sc, `unexpected character ${c}`)
  }
  return tokens
}

const args = process.argv.slice(2)
if (args.length !== 1 || (args[0] !== 'tokens' && args[0] !== 'stats')) {
  process.stderr.write('error: usage: cli.js tokens|stats\n')
  process.exit(2)
}
const input = readFileSync(0, 'utf8')
try {
  const toks = scan(input)
  let out = ''
  if (args[0] === 'tokens') {
    for (const t of toks) out += `${t.line}:${t.col} ${t.kind} ${t.body}\n`
  } else {
    for (const k of KINDS) out += `${k} ${toks.filter((t) => t.kind === k).length}\n`
    out += `total ${toks.length}\n`
  }
  process.stdout.write(out)
} catch (e) {
  if (!(e instanceof ScanError)) throw e
  process.stderr.write(`error: ${e.line}:${e.col}: ${e.message}\n`)
  process.exitCode = 2
}
